      'set_ci':{m.idu for m in musicas.values() if setcontain_ci(m,seq)},
      'contig_exact':{m.idu for m in musicas.values() if contig(m.cifra,seq)},
      'contig_ci':{m.idu for m in musicas.values() if contig([x.lower() for x in m.cifra],[x.lower() for x in seq])},
