from collections import Counter
seqmap={0:['bm','g','d','a'],1:['c','g','am','f'],2:['em','g'],3:['c','a7','dm','g7'],4:['gm','f'],5:['c','c7','f','fm']}
def limpa_cifra(raw_cifra):
    cifra=[]
    for m in raw_cifra:
        if m.strip()!='':
            if '|' in m: cifra.append(m.split('|')[0].split()[0])
            else: cifra += [t for t in m.split()]
    return cifra
rows=[]
with open('data/top/dataset_final.csv',encoding='utf-8',errors='replace') as f:
    f.readline()
    for line in f:
        line=line.replace('"','').replace('NA','')[:-1]
        p=line.split(',')
        p.append(limpa_cifra(p[8].split(';')) if p[8]!='' else [])
        rows.append(p)
def contig(hay,needle):
    n=len(needle); return any(hay[i:i+n]==needle for i in range(len(hay)-n+1))
def subseq(hay,needle):
    it=iter(hay); return all(x in it for x in needle)
print('seq | tag | replica | set | contig | subseq | substrOnly | vocabOnly')
for sid,seq in seqmap.items():
    tag=set(); replica=set(); setc=set(); cont=set(); sub=set(); subonly=set(); voc=set()
    for p in rows:
        idu=p[0]+'_'+p[1]
        raw=p[8].lower(); low=[x.lower() for x in p[9]]; s=';'.join(seq)
        if str(sid) in p[7].split(';'): tag.add(idu)
        # replica of get_famosas
        if s in raw and all(l in seq for l in raw.split(';')): replica.add(idu)
        if set(seq)<=set(low): setc.add(idu)
        if contig(low,seq): cont.add(idu)
        if subseq(low,seq): sub.add(idu)
        if s in raw: subonly.add(idu)
        if all(l in seq for l in raw.split(';')): voc.add(idu)
    print(f'{sid} | {len(tag)} | {len(replica)} | {len(setc)} | {len(cont)} | {len(sub)} | {len(subonly)} | {len(voc)}')
    print('   replica==tag',replica==tag)
