python3 - <<'PY'
seqs={0:['bm','g','d','a'],1:['c','g','am','f'],2:['em','g'],3:['c','a7','dm','g7'],4:['gm','f'],5:['c','c7','f','fm']}
def limpa_cifra(raw_cifra):
    cifra=[]
    for m in raw_cifra:
        if m.strip()!='':
            if '|' in m: cifra.append(m.split('|')[0].split()[0])
            else: cifra += [t for t in m.split()]
    return cifra
rows=[]
with open('data/top/dataset_final.csv',encoding='utf-8',errors='replace') as f:
    f.readline()
    for line in f:
        line=line.replace('"','').replace('NA','')[:-1]
        p=line.split(','); p.append(limpa_cifra(p[8].split(';')) if p[8] else []); rows.append(p)
def contig(h,n):
    return any(h[i:i+len(n)]==n for i in range(len(h)-len(n)+1))
for sid,seq in seqs.items():
    tagged=[]; contig_extra=[]
    for p in rows:
        idu=p[0]+'_'+p[1]; low=[x.lower() for x in p[9]]
        if str(sid) in p[7].split(';'): tagged.append((idu,p[8]))
        elif contig(low,seq): contig_extra.append((idu,p[8]))
    print('=== seq',sid)
    for x in tagged[:2]: print(' TAG',x[0],x[1][:140])
    for x in contig_extra[:2]: print(' CONTIG-ONLY',x[0],x[1][:140])
