def normalizar_acordes(acordes):
    return [acorde.lower() for acorde in acordes]


def sequencia_aparece_em(sequencia, cifra):
    if not sequencia or not cifra:
        return False

    seq = normalizar_acordes(sequencia)
    cifra_norm = normalizar_acordes(cifra)
    seq_tokens = set(seq)

    if any(acorde not in seq_tokens for acorde in cifra_norm):
        return False

    tamanho = len(seq)
    for inicio in range(len(cifra_norm) - tamanho + 1):
        if cifra_norm[inicio:inicio + tamanho] == seq:
            return True

    return False

import unittest

from matching import sequencia_aparece_em


class TestMatching(unittest.TestCase):

    def test_sequencia_exata(self):
        self.assertTrue(sequencia_aparece_em(['Bm', 'G', 'D', 'A'],
                                             ['Bm', 'G', 'D', 'A']))

    def test_ignora_caixa(self):
        self.assertTrue(sequencia_aparece_em(['Bm', 'G', 'D', 'A'],
                                             ['bm', 'g', 'd', 'a']))

    def test_sequencia_contigua_no_meio_da_cifra(self):
        self.assertTrue(sequencia_aparece_em(['G', 'D'],
                                             ['Bm', 'G', 'D', 'A']))

    def test_ordem_invertida_nao_casa(self):
        self.assertFalse(sequencia_aparece_em(['Bm', 'G'],
                                              ['G', 'Bm']))

    def test_preserva_repeticao_interna(self):
        self.assertTrue(sequencia_aparece_em(['C', 'C7'],
                                             ['C', 'C7']))
        self.assertFalse(sequencia_aparece_em(['C', 'C7'],
                                              ['C', 'C', 'C7']))

    def test_acorde_fora_da_sequencia_invalida(self):
        self.assertFalse(sequencia_aparece_em(['Bm', 'G'],
                                              ['Bm', 'G', 'A']))

    def test_repeticao_fora_do_bloco_continua_valida(self):
        self.assertTrue(sequencia_aparece_em(['Bm', 'G'],
                                             ['Bm', 'Bm', 'G']))

    def test_cifra_vazia_nao_casa(self):
        self.assertFalse(sequencia_aparece_em(['Bm', 'G'], []))


if __name__ == '__main__':
    unittest.main()

