const http = require('http');
function getJson(url) { return new Promise((resolve, reject) => { http.get(url, res => { let d=''; res.on('data', c=>d+=c); res.on('end', ()=>resolve(JSON.parse(d))); }).on('error', reject); }); }
(async()=>{
 const list=await getJson('http://127.0.0.1:9222/json/list'); const page=list.find(x=>x.type==='page'&&x.url.includes('5050'));
 const ws=new WebSocket(page.webSocketDebuggerUrl); await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j;});
 let id=0; const pending=new Map(); ws.onmessage=e=>{const m=JSON.parse(e.data); if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);}};
 const send=(method,params={})=>new Promise(r=>{const i=++id;pending.set(i,r);ws.send(JSON.stringify({id:i,method,params}));});
