import json, time, urllib.request
from websocket import create_connection

BASE='http://127.0.0.1:9222'
page = None
for t in json.load(urllib.request.urlopen(BASE + '/json/list')):
    if t.get('type') == 'page':
        page = t
        break
ws = create_connection(page['webSocketDebuggerUrl'], timeout=10)
seq = 0
def cmd(method, params=None):
    global seq
    seq += 1
    ws.send(json.dumps({'id': seq, 'method': method, 'params': params or {}}))
    while True:
        msg = json.loads(ws.recv())
        if msg.get('id') == seq:
            if 'error' in msg:
                raise RuntimeError(msg['error'])
            return msg.get('result', {})

def ev(expr):
    r = cmd('Runtime.evaluate', {'expression': expr, 'returnByValue': True, 'awaitPromise': True})
    if 'exceptionDetails' in r:
        raise RuntimeError(r['exceptionDetails'])
    return r['result'].get('value')

def navigate(url, width=1280, height=800, wait=3):
    cmd('Emulation.setDeviceMetricsOverride', {'width': width, 'height': height, 'deviceScaleFactor': 1, 'mobile': False})
    cmd('Page.navigate', {'url': url})
    time.sleep(wait)

cmd('Page.enable')
cmd('Runtime.enable')

